-- Run this once in Supabase SQL Editor. It repairs only the two seeded users.
update auth.users set confirmation_token=coalesce(confirmation_token,''), recovery_token=coalesce(recovery_token,''), email_change=coalesce(email_change,''), email_change_token_new=coalesce(email_change_token_new,''), email_change_token_current=coalesce(email_change_token_current,''), phone_change=coalesce(phone_change,''), phone_change_token=coalesce(phone_change_token,''), reauthentication_token=coalesce(reauthentication_token,'') where id in ('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222');
delete from auth.identities where provider='email' and (user_id in ('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222') or provider_id in ('admin@kiipl.com','user@kiipl.local','11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222'));
insert into auth.identities (id,user_id,identity_data,provider,provider_id,created_at,updated_at) values
(gen_random_uuid(),'11111111-1111-4111-8111-111111111111',jsonb_build_object('sub','11111111-1111-4111-8111-111111111111','email','admin@kiipl.com'),'email','11111111-1111-4111-8111-111111111111',now(),now()),
(gen_random_uuid(),'22222222-2222-4222-8222-222222222222',jsonb_build_object('sub','22222222-2222-4222-8222-222222222222','email','user@kiipl.local'),'email','22222222-2222-4222-8222-222222222222',now(),now());
